import { BooleanColumn, DocumentIdColumn, Table, StringColumn, TableNameColumn, ReferenceColumn } from '../../db'

export const sys_ux_page_registry = Table({
    name: 'sys_ux_page_registry',
    schema: {
        title: StringColumn({}),
        active: BooleanColumn({}),
        admin_panel_table: TableNameColumn({}),
        admin_panel: DocumentIdColumn({ dependent: 'admin_panel_table' }),
        parent_app: ReferenceColumn({ referenceTable: 'sys_ux_app' }),
        path: StringColumn({}),
        root_macroponent: ReferenceColumn({ referenceTable: 'sys_ux_macroponent' }),
        page: ReferenceColumn({ referenceTable: 'sys_ux_page' }),
    },
})
